                <div class="d-flex gap-3">
                    @foreach (var size in _fontSizes)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="fs-@size" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="fs-@size">@size</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="mb-4">
                <label class="form-label fw-semibold" for="language-select">Language</label>
                <select class="form-select" id="language-select" @bind="_language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang.Key">@lang.Value</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                    <label class="form-check-label" for="compactMode">
                        <strong>Compact Mode</strong>
                        <br /><small class="text-muted">Reduce spacing and padding throughout the UI</small>
                    </label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save
            </button>
        </div>

        <!-- Live Preview -->
        <div class="col-md-5">
            <label class="form-label fw-semibold">Live Preview</label>
            <div class="border rounded @PreviewBackgroundClass" style="@PreviewContainerStyle">
                <div class="@PreviewPaddingClass">
                    <div class="d-flex align-items-center mb-2">
                        <div class="rounded-circle me-2 @PreviewAccentClass"
                             style="width:32px;height:32px;"></div>
                        <div>
                            <strong style="@PreviewFontStyle" class="@PreviewTextClass">Jane Doe</strong>
                            <br />
                            <small class="@PreviewMutedClass" style="@PreviewFontStyle">jane.doe&#64;example.com</small>
                        </div>
                    </div>
                    <hr class="@PreviewBorderClass" />
                    <p class="@PreviewTextClass mb-1" style="@PreviewFontStyle">
                        This is how your content will look with the selected settings.
                    </p>
                    <div class="d-flex gap-2 mt-2">
                        <button class="btn btn-sm @PreviewButtonClass" disabled>Button</button>
                        <button class="btn btn-sm @PreviewButtonOutlineClass" disabled>Secondary</button>
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Español",
        ["fr"] = "Français",
        ["de"] = "Deutsch",
        ["ja"] = "日本語",
        ["zh"] = "中文",
    };

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        await SettingsService.SaveAppearanceAsync(
            new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _successMessage = "Appearance settings saved!";
        _saving = false;
    }

    // Preview computed properties
    private bool IsDark => _theme == "Dark";

    private string PreviewBackgroundClass => IsDark ? "bg-dark" : "bg-white";
    private string PreviewTextClass => IsDark ? "text-light" : "text-dark";
    private string PreviewMutedClass => IsDark ? "text-secondary" : "text-muted";
    private string PreviewAccentClass => IsDark ? "bg-primary" : "bg-primary";
    private string PreviewButtonClass => IsDark ? "btn-light" : "btn-primary";
    private string PreviewButtonOutlineClass => IsDark ? "btn-outline-light" : "btn-outline-primary";
    private string PreviewBorderClass => IsDark ? "border-secondary" : "";
    private string PreviewPaddingClass => _compactMode ? "p-2" : "p-3";

    private string PreviewContainerStyle =>
        $"min-height:200px;transition:all 0.3s ease;";

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size:0.85rem;",
        "Large" => "font-size:1.15rem;",
        _ => "font-size:1rem;",
    };
}
"}

